cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

RWTexture2D<float4> output : register(u0);

float2 hash2(float2 p)
{
    p = float2(dot(p, float2(127.1, 311.7)), dot(p, float2(269.5, 183.3)));
    return -1.0 + 2.0 * frac(sin(p) * 43758.5453);
}

float noise(float2 p)
{
    float2 i = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    return lerp(lerp(dot(hash2(i + float2(0, 0)), f - float2(0, 0)),
                     dot(hash2(i + float2(1, 0)), f - float2(1, 0)), u.x),
                lerp(dot(hash2(i + float2(0, 1)), f - float2(0, 1)),
                     dot(hash2(i + float2(1, 1)), f - float2(1, 1)), u.x), u.y);
}

[numthreads(8, 8, 1)]
void CSMain(uint3 dtid : SV_DispatchThreadID)
{
    uint2 dim;
    output.GetDimensions(dim.x, dim.y);
    if (dtid.x >= dim.x || dtid.y >= dim.y)
        return;

    float2 uv = float2(dtid.xy) / float2(dim);
    float t = time_sim_ms * 0.001;

    float2 vel = float2(0, 0);
    vel.x = noise(uv * 4.0 + float2(0, t * 0.5)) * 0.5;
    vel.y = noise(uv * 4.0 + float2(t * 0.3, 100)) * 0.5;

    if (mouse_buttons & 1) {
        float2 mouseUV = float2(mouse_x, mouse_y) / float2(resolution_x, resolution_y);
        float2 diff = uv - mouseUV;
        float dist = length(diff);
        if (dist < 0.15) {
            float strength = 1.0 - dist / 0.15;
            vel += normalize(float2(-diff.y, diff.x)) * strength * 2.0;
        }
    }

    float n1 = noise(uv * 8.0 + vel * t);
    float n2 = noise(uv * 16.0 - vel * t * 0.5 + 50.0);
    float density = saturate(0.5 + 0.5 * (n1 + n2 * 0.5));

    float speed = length(vel);
    float3 color;
    color.r = saturate(density * 0.3 + speed * 0.5);
    color.g = saturate(density * 0.6 + speed * 0.2);
    color.b = saturate(density * 1.0);

    output[dtid.xy] = float4(color, 1.0);
}
